package com.familyfinance.loan;
import com.familyfinance.shared.Money; import java.time.LocalDate;
public record LoanResponse(long id,String name,LoanType type,Long linkedAssetId,Long memberId,Long assignedUserId,Long paymentAccountId,Long paymentCategoryId,String principal,String annualRate,int termMonths,RepaymentMethod repaymentMethod,LocalDate startOn,String currentPrincipal,LoanStatus status,LoanFundingMode fundingMode,LocalDate accountingOn,Long disbursementAccountId,boolean accountingInitialized,LocalDate lastPaymentOn,Long purchasedAssetId,String scheduledRepaymentTotal,String remainingRepaymentTotal,String paidRepaymentTotal,PrepaymentStrategy latestStrategy,int remainingTerm,LocalDate maturityOn,LocalDate nextPaymentOn,String nextPaymentAmount,int overdueInstallments,String overdueAmount,int overdueDays) {
 static LoanResponse from(Loan l,LoanTotalsService.Totals totals){return new LoanResponse(l.getId(),l.getName(),l.getType(),l.getLinkedAsset()==null?null:l.getLinkedAsset().getId(),l.getMember()==null?null:l.getMember().getId(),l.getAssignedUser()==null?null:l.getAssignedUser().getId(),l.getPaymentAccount().getId(),l.getPaymentCategory().getId(),Money.formatCents(l.getPrincipalCents()),l.getAnnualRate().toPlainString(),l.getTermMonths(),l.getRepaymentMethod(),l.getStartOn(),Money.formatCents(l.getCurrentPrincipalCents()),l.getStatus(),l.getFundingMode(),l.getAccountingOn(),l.getDisbursementAccount()==null?null:l.getDisbursementAccount().getId(),l.getFundingMode()!=null&&l.getAccountingOn()!=null,l.getLastPaymentOn(),l.getPurchasedAssetId(),totals.scheduledRepaymentTotal(),totals.remainingRepaymentTotal(),totals.paidRepaymentTotal(),totals.latestStrategy(),totals.remainingTerm(),totals.maturityOn(),totals.nextPaymentOn(),totals.nextPaymentAmount(),totals.overdueInstallments(),totals.overdueAmount(),totals.overdueDays());}
}
